  "Ces chiffres sont réservés à la direction et aux personnes qui règlent les factures. Demandez à votre consultant le droit « Régler les factures ».": "Diese Zahlen sind der Leitung und den Personen vorbehalten, die Rechnungen bezahlen. Bitten Sie Ihren Berater um das Recht «Rechnungen bezahlen».",
  "La comptabilité n'est pas encore activée sur la base de données.": "Die Buchhaltung ist in der Datenbank noch nicht aktiviert.",
  "Les achats et les marges se lisent déjà ; la saisie du chiffre d'affaires, les charges fixes, les salaires et la banque arriveront avec elle.": "Einkauf und Margen sind bereits lesbar; die Erfassung des Umsatzes, die Fixkosten, die Löhne und die Bank kommen mit ihr.",
  "La comptabilité de l'app prépare vos chiffres et vos pièces pour la fiduciaire. Elle ne tient pas les comptes et n'établit ni le décompte TVA officiel ni les salaires.": "Die Buchhaltung der App bereitet Ihre Zahlen und Belege für die Treuhand vor. Sie führt keine Bücher und erstellt weder die offizielle MWST-Abrechnung noch die Löhne.",
  "Aucun inventaire validé : la période d'inventaire commence au premier inventaire validé.": "Keine bestätigte Inventur: Der Inventurzeitraum beginnt mit der ersten bestätigten Inventur.",
  "Montants TVA comprise, comme sur le ticket de caisse du soir.": "Beträge inkl. MWST, wie auf dem Kassenbeleg am Abend.",
  "La caisse a enregistré": "Die Kasse hat erfasst",
  "ce jour-là. Une saisie ici la remplace pour ce jour.": "an diesem Tag. Eine Erfassung hier ersetzt sie für diesen Tag.",
  "Seule une personne qui règle les factures peut saisir le chiffre d'affaires.": "Nur eine Person, die Rechnungen bezahlt, kann den Umsatz erfassen.",
  "Une charge fixe se saisit une fois : l'app la répartit sur chaque mois. N'importez pas aussi sa facture dans Factures & achats, sinon elle compte deux fois.": "Fixkosten werden einmal erfasst: Die App verteilt sie auf jeden Monat. Importieren Sie die zugehörige Rechnung nicht zusätzlich unter Rechnungen & Einkauf, sonst zählt sie doppelt.",
  "Supprimer cette charge ?": "Diese Fixkosten löschen?",
  "Elle disparaît aussi des mois passés ; pour l'arrêter seulement, indiquez une date de fin.": "Sie verschwinden auch aus den vergangenen Monaten; um sie nur zu beenden, geben Sie ein Enddatum an.",
  "La caisse ne distingue pas la vente à l'emporter : ses montants sont comptés à 8,1 %.": "Die Kasse unterscheidet keinen Verkauf zum Mitnehmen: Ihre Beträge werden zu 8,1 % gezählt.",
  "Estimation prudente ; votre fiduciaire connaît le taux exact.": "Vorsichtige Schätzung; Ihre Treuhand kennt den genauen Satz.",
  "Pour les heures des personnes sans salaire saisi.": "Für die Stunden der Personen ohne erfassten Lohn.",
