  "Cette facture est déjà rapprochée d'une autre ligne du relevé.": "Diese Rechnung ist bereits mit einer anderen Zeile des Kontoauszugs abgeglichen.",
  "Ce fichier CSV n'a pas été reconnu. Téléchargez plutôt le relevé camt.053 dans votre e-banking : toutes les banques suisses le proposent.": "Diese CSV-Datei wurde nicht erkannt. Laden Sie stattdessen den Kontoauszug camt.053 in Ihrem E-Banking herunter: Alle Schweizer Banken bieten ihn an.",
  "Ce fichier n'est pas un relevé camt.053. Téléchargez le relevé camt.053 (et non une notification camt.054) dans votre e-banking.": "Diese Datei ist kein Kontoauszug camt.053. Laden Sie den Kontoauszug camt.053 (und keine Mitteilung camt.054) in Ihrem E-Banking herunter.",
  "Lecture des relevés impossible pour l'instant. Nouvel essai en cours.": "Kontoauszüge können gerade nicht gelesen werden. Neuer Versuch läuft.",
  "Téléchargez le relevé camt.053 de votre compte dans l'e-banking (ou son export CSV), puis importez-le ici : l'app propose la facture de chaque paiement, vous validez.": "Laden Sie den Kontoauszug camt.053 Ihres Kontos im E-Banking herunter (oder seinen CSV-Export) und importieren Sie ihn hier: Die App schlägt zu jeder Zahlung die Rechnung vor, Sie bestätigen.",
  "Une facture encore à régler, rapprochée ici, est marquée réglée à la date du relevé, par virement.": "Eine noch offene Rechnung, die hier abgeglichen wird, wird zum Datum des Kontoauszugs als per Überweisung bezahlt markiert.",
  "Les encaissements ne se rapprochent pas des factures d'achat.": "Einzahlungen werden nicht mit Einkaufsrechnungen abgeglichen.",
  "Défaire un rapprochement qui a réglé la facture propose de la remettre à régler ; un règlement saisi dans Factures & achats ne change pas.": "Wird ein Abgleich rückgängig gemacht, der die Rechnung bezahlt hat, wird vorgeschlagen, sie wieder als offen zu setzen; eine unter Rechnungen & Einkauf erfasste Zahlung ändert sich nicht.",
  "ligne déjà importée sera ignorée.": "bereits importierte Zeile wird übersprungen.",
  "lignes déjà importées seront ignorées.": "bereits importierte Zeilen werden übersprungen.",
  "Toutes les lignes de ce relevé sont déjà importées.": "Alle Zeilen dieses Kontoauszugs sind bereits importiert.",
  "ligne a la même date et le même montant qu'une ligne déjà importée : le même relevé, sous un autre format ? Importé deux fois, il compterait deux fois.": "Zeile hat dasselbe Datum und denselben Betrag wie eine bereits importierte Zeile: derselbe Kontoauszug in einem anderen Format? Zweimal importiert, würde er doppelt zählen.",
  "lignes ont la même date et le même montant qu'une ligne déjà importée : le même relevé, sous un autre format ? Importé deux fois, il compterait deux fois.": "Zeilen haben dasselbe Datum und denselben Betrag wie eine bereits importierte Zeile: derselbe Kontoauszug in einem anderen Format? Zweimal importiert, würde er doppelt zählen.",
  "Rien n'est rapproché ni réglé à l'import : l'app propose ensuite la facture de chaque paiement, vous validez.": "Beim Import wird nichts abgeglichen und nichts bezahlt: Die App schlägt danach zu jeder Zahlung die Rechnung vor, Sie bestätigen.",
  "Importez un relevé bancaire pour partir du solde réel.": "Importieren Sie einen Kontoauszug, um vom tatsächlichen Saldo auszugehen.",
  "Entrées estimées : moyenne du chiffre d'affaires des 28 derniers jours.": "Geschätzte Einnahmen: Durchschnitt des Umsatzes der letzten 28 Tage.",
