  "Cochez les préparations maison à compter : leur prix est le coût matière de la fiche.": "Kreuzen Sie die zu zählenden hausgemachten Zubereitungen an: Ihr Preis entspricht dem Warenaufwand des Rezeptblatts.",
  "Cochez une catégorie entière ou quelques produits : unité et prix viennent du catalogue.": "Kreuzen Sie eine ganze Kategorie oder einzelne Produkte an: Einheit und Preis stammen aus dem Katalog.",
