  "Encaissez-les ou annulez-les d'abord. Sinon ils passeront au jour suivant : un ticket encaissé après la clôture appartient au lendemain.": "Kassieren oder stornieren Sie sie zuerst. Sonst gehen sie auf den nächsten Tag über: Ein nach dem Abschluss kassierter Bon gehört zum Folgetag.",
