  "Une clôture ne se modifie pas. Pour corriger un comptage, vous pouvez enregistrer une clôture complémentaire, avec un motif.": "Ein Abschluss wird nicht geändert. Um eine Zählung zu korrigieren, können Sie einen ergänzenden Abschluss mit einem Grund erfassen.",
