  "TVA et clôture": "MWST und Abschluss",
  "Taux de TVA par catégorie": "MWST-Satz pro Kategorie",
  "Sur place, le taux de la catégorie s'applique. Quand un ticket est marqué à emporter, seules les catégories cochées passent au taux réduit ; l'alcool reste toujours au taux normal. Le taux est figé sur chaque ligne à l'encaissement.": "Vor Ort gilt der Satz der Kategorie. Wird ein Bon als Mitnahme markiert, wechseln nur die angekreuzten Kategorien zum reduzierten Satz; Alkohol bleibt immer beim Normalsatz. Der Satz wird beim Kassieren auf jeder Zeile festgehalten.",
  "Taux réduit à emporter": "Reduzierter Satz für Mitnahme",
  "Un article libre, ou un produit hors de ces catégories, reste au taux normal, à emporter compris.": "Ein freier Artikel oder ein Produkt ausserhalb dieser Kategorien bleibt beim Normalsatz, auch zum Mitnehmen.",
