  "Sans numéro de TVA, la quittance ne porte pas la mention exigée d'un assujetti. La caisse ne l'invente jamais.": "Ohne MWST-Nummer trägt die Quittung nicht den für Steuerpflichtige vorgeschriebenen Vermerk. Die Kasse erfindet sie nie.",
