  "Durée entre l'arrivée et le départ pointés, pause déduite ; un horaire sans départ pointé ne compte pas.": "Dauer zwischen gestempelter Ankunft und gestempeltem Weggang, Pause abgezogen; ein Dienst ohne gestempelten Weggang zählt nicht.",
