  "Ce poste est en mode test : rien de ce qui s'y vend ne compte dans les chiffres. Pour revenir aux vraies ventes, ouvrez la caisse et touchez « Quitter le mode test » dans le bandeau.": "Dieses Gerät ist im Testmodus: Nichts, was hier verkauft wird, zählt in den Zahlen. Um zu den echten Verkäufen zurückzukehren, öffnen Sie die Kasse und tippen Sie im Banner auf «Testmodus verlassen».",
