  "Comme l'appareil suit le réglage clair ou sombre du téléphone, de la tablette ou de l'ordinateur. Le bouton de la barre du haut bascule entre clair et sombre.": "Wie das Gerät folgt der hellen oder dunklen Einstellung des Telefons, des Tablets oder des Computers. Die Schaltfläche in der oberen Leiste wechselt zwischen hell und dunkel.",
  "Le texte de l'app sur cet appareil. Les exports PDF ne changent pas.": "Der Text der App auf diesem Gerät. Die PDF-Exporte ändern sich nicht.",
  "Hauteur des lignes, des boutons et des champs, et marges de la page. Compacte se règle à la souris : au doigt, chaque cible garde 44 px.": "Höhe der Zeilen, Schaltflächen und Felder sowie Seitenränder. Kompakt wird mit der Maus eingestellt: Mit dem Finger behält jedes Ziel 44 px.",
  "Le bouton principal, la pilule choisie et l'entrée choisie du menu. Pétrole est la couleur de la marque.": "Die Hauptschaltfläche, die gewählte Pille und der gewählte Menüeintrag. Petrol ist die Farbe der Marke.",
  "Plus de fondus ni de glissements : les écrans changent d'un coup.": "Keine Überblendungen und kein Gleiten mehr: Die Ansichten wechseln auf einmal.",
  "Textes secondaires plus foncés, filets et contours plus marqués.": "Sekundäre Texte dunkler, Linien und Konturen deutlicher.",
  "Original garde le texte tel qu'il a été saisi. English, Español et Deutsch traduisent l'écran, pas les données. Le sélecteur de la barre du haut fait la même chose.": "Original behält den Text so, wie er erfasst wurde. English, Español und Deutsch übersetzen den Bildschirm, nicht die Daten. Die Auswahl in der oberen Leiste macht dasselbe.",
  "Ouvrir l'app sur": "App öffnen auf",
