  "Au lancement, sur cet appareil. Une notification touchée ouvre toujours sa page, et un rechargement garde la page en cours.": "Beim Start, auf diesem Gerät. Eine angetippte Mitteilung öffnet immer ihre Seite, und ein Neuladen behält die aktuelle Seite.",
